<?php
require 'common.php';require_admin();$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(string)($_POST['id']??'');$status=(string)($_POST['status']??'new');if(isset(quote_statuses()[$status])&&update_quote_status($id,$status))$notice='تم تحديث حالة الطلب.';}
$filter=(string)($_GET['status']??'');$rows=array_reverse(quotes());if($filter!=='')$rows=array_values(array_filter($rows,fn($q)=>($q['status']??'new')===$filter));admin_head('طلبات عروض الأسعار');?>
<?php if($notice):?><div class="ok-box"><?=e($notice)?></div><?php endif;?>
<section class="metric-grid"><?php $all=quotes();foreach(quote_statuses() as$k=>$label){$count=count(array_filter($all,fn($q)=>($q['status']??'new')===$k));metric($label,(string)$count,'RFQ',''.($k==='new'?'red':($k==='won'?'green':'silver')));}?></section>
<section class="panel"><div class="panel-head"><div><span>PROCUREMENT PIPELINE</span><h2>إدارة RFQ</h2></div><div class="filter-links"><a href="quotes.php">الكل</a><?php foreach(quote_statuses() as$k=>$label):?><a class="<?=$filter===$k?'active':''?>" href="quotes.php?status=<?=e($k)?>"><?=e($label)?></a><?php endforeach;?></div></div><div class="table-wrap"><table><thead><tr><th>المرجع</th><th>العميل / الشركة</th><th>التواصل</th><th>الطلب</th><th>الحالة</th><th>التاريخ</th></tr></thead><tbody><?php foreach($rows as$q):?><tr><td><b><?=e((string)($q['id']??''))?></b></td><td><?=e((string)($q['company']??$q['name']??'—'))?><small><?=e((string)($q['name']??''))?></small></td><td><?=e((string)($q['phone']??$q['email']??'—'))?></td><td class="request-cell"><?=e((string)($q['request']??$q['message']??'—'))?></td><td><form method="post" class="status-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e((string)($q['id']??''))?>"><select name="status" onchange="this.form.submit()"><?php foreach(quote_statuses() as$k=>$label):?><option value="<?=e($k)?>" <?=($q['status']??'new')===$k?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></form></td><td><?=e(substr((string)($q['created_at']??''),0,16))?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="muted-cell">لا توجد طلبات ضمن هذا الفلتر.</td></tr><?php endif;?></tbody></table></div></section>
<?php admin_foot();?>